//go:build !linux && !darwin

package icmp

import (
	"errors"
	"runtime"
)

// Open creates and configures an ICMP socket. It prefers an unprivileged
// datagram socket and falls back to a raw socket (the order is reversed for
// root or when cfg.PreferRaw is set).
func Open(cfg Config) (Conn, error) {
	return nil, errors.New("ICMP sockets are not supported on " + runtime.GOOS + " (only linux and darwin)")
}

// LocalErrorText describes an error generated by the local host.
func LocalErrorText(e *Event) string { return "local error" }
